const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={record:null,shared:null}; let w,callbacks;
export const isEditor=()=>!state.shared;
export const organisationMembers=()=>[];
export const demoRuntime=()=>true;
export const communityRuntime=()=>true;
export const sharedPreview=()=>!!state.shared;
export const isFeature=()=>true;
export const assigneeField=()=>'';
export const decorateDrawer=()=>{};
export function setBusy(value){$('#roadmap-select').disabled=value;$('#new-roadmap').disabled=value;}
function toast(m,e=false){callbacks.toast(m,e);}
function download(data,name,type='text/markdown'){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function modal(title,content){const d=$('#platform-dialog');if(d.open)d.close();d.innerHTML=`<h2>${esc(title)}</h2><button id="close-platform" class="close" aria-label="Close">${icon("close")}</button><div id="platform-error" role="alert" hidden></div>${content}`;$('#close-platform').onclick=()=>d.close();d.showModal();return d;}
function errorInModal(e){$('#platform-error').textContent=e.message;$('#platform-error').hidden=false;}
function formAction(f,fn){f.onsubmit=async e=>{e.preventDefault();try{await fn(new FormData(f));}catch(e){errorInModal(e);}};}
async function ask(title,description){return confirm(title+'\n'+description);}
function heading(t,d,a=''){return `<div class="section-heading"><div><h1>${esc(t)}</h1><p>${esc(d)}</p></div>${a}</div>`;}
function persist(next){w=writeWorkspace(localStorage,next,w.revision);}
function mutate(fn){const next=structuredClone(w);const result=fn(next);persist(next);return result;}
export async function saveRoadmap(roadmap,revision){if(!isEditor())throw Error('Save a copy before editing.');const id=state.record.id;mutate(next=>saveRecord(next,id,roadmap,revision));state.record=w.roadmaps.find(r=>r.id===id);refresh();return state.record;}
function refresh(){const rows=state.shared?[state.record]:w.roadmaps;$('#roadmap-select').innerHTML=rows.map(r=>`<option value="${esc(r.id)}">${esc(r.roadmap.title)}</option>`).join('');$('#roadmap-select').value=state.record?.id||'';const views=w.views.filter(v=>v.roadmapId===state.record?.id);$('#saved-views').innerHTML=views.map((v,i)=>`<button data-local-view="${i}">${esc(v.name)}</button>`).join('');document.querySelectorAll('[data-local-view]').forEach(b=>b.onclick=()=>callbacks.applyFilter(views[+b.dataset.localView]));}
function markSidebar(kind,id){
  document.querySelectorAll('.sidebar nav [data-view],.sidebar nav [data-page]').forEach(button=>{
    const active=button.dataset[kind]===id&&button.hasAttribute('data-'+kind);
    button.classList.toggle('active',active);
    if(active)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');
  });
}
function showRoadmap(selectedView){ markSidebar('view',selectedView||document.querySelector('.view-tabs [data-view].active')?.dataset.view||'roadmap');$('#workspace-panel').hidden=true;$('#roadmap-content').hidden=false;$('#add-activity').hidden=!isEditor();$('#settings').disabled=!isEditor();$('#import').hidden=!isEditor();$('#new-roadmap').hidden=!isEditor();$('#choose-example').hidden=!isEditor();$('#save-plan-link').hidden=!isEditor();for(const id of ['collaboration','save-filter','save-template'])$('#'+id).hidden=!isEditor();}
function openRecord(id){callbacks.contextChange();state.record=w.roadmaps.find(r=>r.id===id)||null;refresh();showRoadmap();if(state.record){history.replaceState(null,'',makePlanUrl(new URL('./',location.href).href,state.record.id));callbacks.open(state.record);}else callbacks.clear();}
function newRoadmap(source=seedRoadmap()){if(!isEditor())return;const title=prompt('Roadmap title',source.title);if(!title)return;let id;mutate(next=>{id=appendRoadmap(next,{...source,title}).id;});openRecord(id);}
function showPage(page){if(state.shared&&page!=='workstreams')return;markSidebar('page',page);$('#roadmap-content').hidden=true;$('#workspace-panel').hidden=false;try{if(page==='workstreams')workstreamsPage();else if(page==='data')dataPage();else if(page==='library')libraryPage();else if(page==='portfolio'||page==='reports')portfolioPage();}catch(e){toast(e.message,true);}}
function libraryPage(){
  const rows=[...w.roadmaps].sort((a,b)=>b.updatedAt-a.updatedAt);
  $('#workspace-panel').innerHTML=heading('Your roadmap library','Every plan saved in this browser, newest first. Open a plan or copy its direct bookmark link.')+
    '<div class="feature-note">These plans are saved in this browser, not in a cloud account. Bookmark links only work here while this browser retains the workspace. <a href="./docs/saving.html">How to save and return</a></div>'+
    '<div class="library-list">'+rows.map(r=>'<article class="library-card"><div class="library-card-main"><span class="library-card-eyebrow">SAVED ROADMAP</span><h2>'+esc(r.roadmap.title)+'</h2><p>'+esc(r.roadmap.client)+' · '+r.roadmap.tracks.length+' workstreams · '+r.roadmap.activities.length+' activities</p><small>Edited '+esc(new Date(r.updatedAt).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}))+' · Revision '+r.revision+'</small></div><div class="library-card-actions"><button class="button primary" data-open="'+esc(r.id)+'">Open plan</button><button class="button" data-copy-plan="'+esc(r.id)+'">Copy link</button></div></article>').join('')+'</div>'+
    '<h2 class="library-templates-title">Reusable templates</h2>'+ (w.templates.length?w.templates.map(t=>'<p><button class="button" data-template="'+esc(t.id)+'">'+esc(t.name)+'</button></p>').join(''):'<p>No templates saved yet. Choose “Save template” while editing a plan.</p>');
  document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openRecord(b.dataset.open));
  document.querySelectorAll('[data-copy-plan]').forEach(b=>b.onclick=()=>planLinkDialog(b.dataset.copyPlan));
  document.querySelectorAll('[data-template]').forEach(b=>b.onclick=()=>newRoadmap(w.templates.find(t=>t.id===b.dataset.template).roadmap));
}
function portfolioPage(){const rows=w.roadmaps.map(r=>({id:r.id,title:r.roadmap.title,client:r.roadmap.client,revision:r.revision,activities:r.roadmap.activities.length,done:r.roadmap.activities.filter(a=>a.status==='Done').length,inProgress:r.roadmap.activities.filter(a=>a.status==='In progress').length})),report={id:newId(),at:Date.now(),roadmaps:rows,totals:{roadmaps:rows.length,activities:rows.reduce((n,r)=>n+r.activities,0),done:rows.reduce((n,r)=>n+r.done,0),inProgress:rows.reduce((n,r)=>n+r.inProgress,0)}};$('#workspace-panel').innerHTML=heading('Portfolio & reports','Progress across every roadmap.')+`<button class="button" id="report-download">Save report</button><table><thead><tr><th>Roadmap</th><th>Activities</th><th>Done</th><th>In progress</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.title)}</td><td>${r.activities}</td><td>${r.done}</td><td>${r.inProgress}</td></tr>`).join('')}</tbody></table>`;$('#report-download').onclick=()=>{mutate(n=>n.reports.push(report));download(reportToMarkdown(report),'portfolio-report.md');};}
function dataPage(){ $('#workspace-panel').innerHTML=heading('Data backup','Export or import the complete workspace: roadmaps, templates, history, notes, reviews, reports and saved views.')+'<button id="backup-md" class="button">Export Markdown</button> <button id="backup-csv" class="button">Export CSV</button><p>Workspace CSV uses one row per record with a JSON detail column. Individual roadmap CSV is designed for spreadsheet editing.</p><input id="backup-file" type="file" accept=".md,.csv"><div id="backup-preview"></div>';$('#backup-md').onclick=()=>download(workspaceToMarkdown(w),'mightora-workspace.md');$('#backup-csv').onclick=()=>download(workspaceToCsv(w),'mightora-workspace.csv','text/csv');$('#backup-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>MAX_BACKUP_BYTES)throw Error('Backup exceeds 50 MB.');const text=await f.text(),input=f.name.toLowerCase().endsWith('.csv')?workspaceFromCsv(text):workspaceFromMarkdown(text);const expected=w.revision;$('#backup-preview').innerHTML=`<p>Validated backup: ${input.roadmaps.length} roadmaps, ${input.templates.length} templates, ${input.snapshots.length} historical versions.</p><select id="backup-mode"><option value="add">Add as new content</option><option value="replace">Replace workspace</option></select><button id="apply-backup" class="button primary">Import validated backup</button>`;$('#apply-backup').onclick=()=>{try{if(w.revision!==expected)throw Error('Workspace changed. Preview the file again.');const mode=$('#backup-mode').value;if(mode==='replace'&&!confirm('Replace the entire workspace? A safety backup will download first.'))return;if(mode==='replace')download(workspaceToMarkdown(w),'before-import.md');persist(importWorkspace(w,input,mode));openRecord(w.roadmaps[0]?.id);toast('Workspace imported.');}catch(e){toast(e.message,true);}};}catch(e){toast(e.message,true);}};}
function discussion(){if(!state.record)return;const id=state.record.id;modal('Notes, reviews & history',`<form id="note-form"><label class="field">Author<input name="author" required maxlength="100" value="Me"></label><label class="field">Note<textarea name="text" required maxlength="2000"></textarea></label><button class="button" type="submit">Add note</button></form><form id="review-form"><label class="field">Reviewer<input name="reviewer" required maxlength="100"></label><select name="status"><option>Pending</option><option>Approved</option><option>Changes requested</option></select><button class="button">Record review</button></form><h3>Notes</h3>${w.comments.filter(c=>c.roadmapId===id).map(c=>`<p><strong>${esc(c.author)}</strong>: ${esc(c.text)}</p>`).join('')}<h3>Reviews</h3>${w.reviews.filter(r=>r.roadmapId===id).map(r=>`<p>${esc(r.reviewer)}: ${esc(r.status)} · revision ${r.revision}</p>`).join('')}<h3>History</h3>${w.snapshots.filter(s=>s.roadmapId===id).reverse().map(s=>`<p>Revision ${s.revision} <button data-restore="${esc(s.id)}">Restore</button></p>`).join('')}`);formAction($('#note-form'),async d=>{mutate(n=>n.comments.push({id:newId(),roadmapId:id,activityId:null,author:d.get('author'),text:d.get('text'),at:Date.now()}));discussion();});formAction($('#review-form'),async d=>{mutate(n=>n.reviews.push({id:newId(),roadmapId:id,revision:state.record.revision,reviewer:d.get('reviewer'),status:d.get('status'),note:'',at:Date.now()}));discussion();});document.querySelectorAll('[data-restore]').forEach(b=>b.onclick=async()=>{try{const s=w.snapshots.find(s=>s.id===b.dataset.restore);if(confirm('Restore this version? The current version will remain in history.')){await saveRoadmap(s.roadmap,state.record.revision);callbacks.open(state.record);discussion();}}catch(e){errorInModal(e);}});}
function examplePicker(selected='chemistry'){
  if(!isEditor())return;
  modal('Choose an industry example',`<p>Start with a small, editable plan. This creates a new roadmap and keeps your existing work.</p><label class="field"><span>Industry</span><select id="example-sector">${EXAMPLES.map(e=>`<option value="${e.id}" ${e.id===selected?'selected':''}>${esc(e.name)}</option>`).join('')}</select></label><div id="example-preview" class="example-preview"></div><button id="use-example" class="button primary">Create roadmap from example</button>`);
  const preview=()=>{const e=EXAMPLES.find(e=>e.id===$('#example-sector').value),r=exampleRoadmap(e.id);$('#example-preview').innerHTML=`<h3>${esc(e.title)}</h3><p>${esc(e.description)}</p><p>4 quarters · ${r.tracks.length} workstreams · ${r.activities.length} activities</p><ul>${r.tracks.map(t=>`<li>${esc(t.name)}</li>`).join('')}</ul><p>Illustrative dates and activities. Adapt them to your project.</p><a href="./examples/${e.id}.html" target="_blank" rel="noopener">Read the full example</a>`;};
  $('#example-sector').onchange=preview;preview();$('#use-example').onclick=()=>{try{let id;mutate(n=>{id=appendRoadmap(n,exampleRoadmap($('#example-sector').value)).id;});$('#platform-dialog').close();openRecord(id);toast('Example copied into your workspace.');}catch(e){errorInModal(e);}};
}
export async function initialise(options){callbacks=options;try{w=loadWorkspace(localStorage);$('#auth-screen').hidden=true;$('#application-shell').hidden=false;document.body.classList.remove('signed-out');$('#runtime-banner').hidden=false;$('#runtime-banner').textContent='Saved in this browser · all features are free · export backups to keep or move your work';$('#roadmap-select').onchange=e=>openRecord(e.target.value);$('#new-roadmap').onclick=()=>newRoadmap();$('#choose-example').onclick=()=>examplePicker();document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>showPage(b.dataset.page));document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>showRoadmap(b.dataset.view)));$('#share-roadmap').onclick=shareDialog;$('#publish-roadmap').onclick=publishDialog;$('#save-plan-link').onclick=()=>planLinkDialog();$('#collaboration').onclick=discussion;$('#svg-export').onclick=exportImage;$('#pdf-export').onclick=exportPdf;$('#save-template').onclick=()=>{const name=prompt('Template name');if(name)mutate(n=>n.templates.push({id:newId(),name,roadmap:structuredClone(state.record.roadmap),createdAt:Date.now()}));};$('#save-filter').onclick=()=>{const name=prompt('View name');if(name){mutate(n=>n.views.push({id:newId(),roadmapId:state.record.id,name,...callbacks.getFilter()}));refresh();}};const shared=await readShareHash(location.hash);if(shared){state.shared=shared;state.record={id:'shared-preview',roadmap:shared,revision:0};refresh();showRoadmap();callbacks.open(state.record);$('#shared-preview-bar').hidden=false;$('#shared-preview-bar').innerHTML='<p>Read-only snapshot. Changes do not sync.</p><button id="save-copy" class="button">Save a copy & edit</button>';$('#save-copy').onclick=()=>{state.shared=null;$('#shared-preview-bar').hidden=true;location.hash='workspace';newRoadmap(shared);};}else {const params=new URLSearchParams(location.search),requested=requestedPlanId(location.search),example=params.get('example');const target=requested&&w.roadmaps.find(r=>r.id===requested);openRecord(target?.id||[...w.roadmaps].sort((a,b)=>b.updatedAt-a.updatedAt)[0]?.id);if(requested&&!target)toast('This saved plan was not found in this browser. Restore a workspace backup to recover it.',true);if(EXAMPLES.some(e=>e.id===example))examplePicker(example);}window.addEventListener('storage',e=>{if(e.key==='mightora-local-workspace-v1')toast('Workspace changed in another tab. Reload before editing.',true);});}catch(e){toast(e.message,true);}}
function shareDialog(){
  if(!state.record)return;modal('Share a roadmap snapshot','<p>Create a self-contained link that opens this roadmap in the app. Anyone with the link can read the included content. It does not include workspace notes or history.</p><label class="dependency-option"><input type="checkbox" id="share-owners"><span>Include owner names (off by default)</span></label><label class="dependency-option"><input type="checkbox" id="share-descriptions" checked><span>Include activity descriptions</span></label><div class="dialog-actions"><button type="button" id="generate-share-link" class="button primary">Generate link</button></div><div id="generated-share-link"></div>');
  $('#generate-share-link').onclick=async()=>{const b=$('#generate-share-link');b.disabled=true;try{const url=await makeShareUrl(callbacks.getRoadmap(),location.href,{includeOwners:$('#share-owners').checked,includeDescriptions:$('#share-descriptions').checked});$('#generated-share-link').innerHTML=`<label class="field"><span>Share link · snapshot of the current roadmap</span><textarea id="share-url" readonly rows="4">${esc(url)}</textarea></label><button class="button" id="copy-share-url">Copy link</button><p class="field-note">Changes require a new link. If a messaging app truncates a long link, send the Markdown file instead.</p>`;$('#copy-share-url').onclick=async()=>{try{await navigator.clipboard.writeText(url);toast('Share link copied.');}catch{$('#share-url').focus();$('#share-url').select();toast('Select and copy the link from the field.');}};}catch(error){errorInModal(error);}finally{b.disabled=false;}};
}
async function commitWorkstreams(next){
  setBusy(true);let record;try{record=await saveRoadmap(next,state.record.revision);}finally{setBusy(false);}callbacks.open(record);workstreamsPage();toast('Workstreams updated.');
}
function workstreamsPage(){
  if(!state.record)throw new Error('Select or create a roadmap before editing its workstreams.');
  const r=state.record.roadmap,editable=isEditor();
  $('#workspace-panel').innerHTML=heading('Workstreams',`${r.title} · ${r.tracks.length} of 20 workstreams. Each workstream is a row on the roadmap.`,editable?'<button class="button primary" id="new-workstream">+ Add workstream</button>':'')+`<div class="feature-note">Edit the names and colours, reorder rows, or add new workstreams. Removing a populated workstream moves its activities to a destination you choose; activity dates and dependency links are preserved.</div><div class="workstream-list">${r.tracks.map((t,i)=>`<article class="workstream-editor"><form data-edit-workstream="${esc(t.id)}"><div class="workstream-position">${String(i+1).padStart(2,'0')}</div><label class="field workstream-name"><span>Workstream name</span><input name="name" value="${esc(t.name)}" maxlength="80" required ${editable?'':'disabled'}></label><label class="field workstream-colour"><span>Colour</span><input name="color" type="color" value="${esc(t.color)}" ${editable?'':'disabled'}></label><span class="workstream-count">${r.activities.filter(a=>a.trackId===t.id).length} activities</span>${editable?'<button type="submit" class="button">Save</button>':''}</form><div class="workstream-actions">${editable?`<button class="button small" data-reorder-track="${esc(t.id)}" data-direction="-1" ${i===0?'disabled':''} aria-label="Move ${esc(t.name)} up">${icon("arrow-up")} Move up</button><button class="button small" data-reorder-track="${esc(t.id)}" data-direction="1" ${i===r.tracks.length-1?'disabled':''} aria-label="Move ${esc(t.name)} down">${icon("arrow-down")} Move down</button><button class="text-button" data-delete-track="${esc(t.id)}" ${r.tracks.length===1?'disabled':''}>Remove workstream</button>`:''}</div></article>`).join('')}</div>`;
  $('#new-workstream')?.addEventListener('click',()=>{modal('Add a workstream','<form id="add-workstream-form"><label class="field"><span>Workstream name</span><input name="name" required maxlength="80" placeholder="e.g. Data & integration"></label><label class="field"><span>Colour</span><input name="color" type="color" value="#059669"></label><div class="dialog-actions"><button class="button primary" type="submit">Add workstream</button></div></form>');formAction($('#add-workstream-form'),async d=>{const next=addWorkstream(state.record.roadmap,d.get('name'),d.get('color'));await commitWorkstreams(next);$('#platform-dialog').close();});});
  document.querySelectorAll('[data-edit-workstream]').forEach(form=>form.onsubmit=async e=>{e.preventDefault();const d=new FormData(form);try{await commitWorkstreams(editWorkstream(state.record.roadmap,form.dataset.editWorkstream,d.get('name'),d.get('color')));}catch(error){toast(error.message,true);}});
  document.querySelectorAll('[data-reorder-track]').forEach(b=>b.onclick=async()=>{try{await commitWorkstreams(reorderWorkstream(state.record.roadmap,b.dataset.reorderTrack,Number(b.dataset.direction)));}catch(error){toast(error.message,true);}});
  document.querySelectorAll('[data-delete-track]').forEach(b=>b.onclick=async()=>{const id=b.dataset.deleteTrack,r=state.record.roadmap,t=r.tracks.find(t=>t.id===id),count=r.activities.filter(a=>a.trackId===id).length;
    if(!count){if(await ask('Remove this empty workstream?',t.name))try{await commitWorkstreams(removeWorkstream(r,id));}catch(error){toast(error.message,true);}return;}
    modal('Move activities & remove workstream',`<p>“${esc(t.name)}” contains ${count} activities. Choose where to move them before removing this row. Dates, activity IDs and dependency links will stay intact.</p><form id="remove-workstream-form"><label class="field"><span>Move activities into</span><select name="destination" required>${r.tracks.filter(t=>t.id!==id).map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('')}</select></label><div class="dialog-actions"><button class="button primary" type="submit">Move ${count} activities & remove</button></div></form>`);
    formAction($('#remove-workstream-form'),async d=>{await commitWorkstreams(removeWorkstream(state.record.roadmap,id,d.get('destination')));$('#platform-dialog').close();});
  });
}
function svgRoadmap(){
  const r=callbacks.getRoadmap(),col=220,left=230,header=110,row=170,width=left+r.periodCount*col,height=header+r.tracks.length*row+45;
  const wrap=(s,n=29)=>{const words=s.split(/\s+/),lines=[''];for(const word of words){if((lines.at(-1)+' '+word).length>n&&lines.at(-1))lines.push(word);else lines[lines.length-1]+=(lines.at(-1)?' ':'')+word;}return lines;};
  const maxCount=Math.max(1,...r.tracks.flatMap(t=>Array.from({length:r.periodCount},(_,q)=>r.activities.filter(a=>a.trackId===t.id&&quarterOf(a.start,r)===q).length)));const actualRow=Math.max(row,maxCount*125+20),actualHeight=header+r.tracks.length*actualRow+45;
  let svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${actualHeight}" viewBox="0 0 ${width} ${actualHeight}"><rect width="100%" height="100%" fill="#fff"/><g font-family="system-ui, sans-serif" fill="#111827"><text x="20" y="32" font-size="23" font-weight="700">${esc(r.title)}</text><text x="20" y="55" font-size="12" fill="#6b7280">${esc(r.client)} · activity start quarter · ${esc('Local workspace')}</text>`;
  for(let q=0;q<r.periodCount;q++){const p=periodLabel(r,q);svg+=`<rect x="${left+q*col}" y="70" width="${col}" height="40" fill="#ecfdf5" stroke="#e5e7eb"/><text x="${left+q*col+12}" y="95" font-size="12" font-weight="600">${esc(p.title)} · ${p.phase} · ${p.start.slice(0,7)}</text>`;}
  r.tracks.forEach((t,i)=>{const y=header+i*actualRow;svg+=`<rect x="0" y="${y}" width="${width}" height="${actualRow}" fill="${i%2?'#f9fafb':'#fff'}" stroke="#e5e7eb"/>`;wrap(t.name,24).forEach((line,j)=>svg+=`<text x="20" y="${y+30+j*20}" font-size="13" font-weight="600">${esc(line)}</text>`);for(let q=0;q<r.periodCount;q++){const x=left+q*col;svg+=`<path d="M${x} ${y} V${y+actualRow}" stroke="#e5e7eb"/>`;r.activities.filter(a=>a.trackId===t.id&&quarterOf(a.start,r)===q).forEach((a,j)=>{const cy=y+10+j*125;svg+=`<rect x="${x+8}" y="${cy}" width="${col-16}" height="115" rx="6" fill="#fff" stroke="#d1d5db"/><rect x="${x+8}" y="${cy}" width="4" height="115" rx="2" fill="${t.color}"/>`;wrap(a.title).slice(0,3).forEach((line,k)=>svg+=`<text x="${x+20}" y="${cy+23+k*16}" font-size="11" font-weight="600">${esc(line)}</text>`);svg+=`<text x="${x+20}" y="${cy+84}" font-size="10" fill="#047857">${esc(a.status)} · ${a.dependencies.length} prerequisites</text><text x="${x+20}" y="${cy+102}" font-size="9" fill="#6b7280">${esc(a.start)} → ${esc(a.end)}</text>`;});}});return svg+`<text x="20" y="${actualHeight-15}" font-size="10" fill="#6b7280">${'Mightora Roadmaps'} · exported ${new Date().toISOString().slice(0,10)}</text></g></svg>`;
}
function exportImage(){if(!isFeature('exports')){toast('Image and PDF exports are available with Pathfinder and Atlas.',true);return;}download(svgRoadmap(),'roadmap.svg','image/svg+xml');}
function exportPdf(){if(!isFeature('exports')){toast('Image and PDF exports are available with Pathfinder and Atlas.',true);return;}const w=window.open('','_blank');if(!w){toast('Allow the print window to open, then try again.',true);return;}w.document.write(`<!doctype html><html><head><title>Roadmap export</title><style>@page{size:A3 landscape;margin:10mm}body{margin:0}svg{width:100%;height:auto}</style></head><body>${svgRoadmap()}</body></html>`);w.document.close();w.focus();setTimeout(()=>w.print(),300);}

function planLinkDialog(id=state.record?.id){
  const record=w.roadmaps.find(r=>r.id===id);
  if(!record)return;
  const url=makePlanUrl(new URL('./',location.href).href,id);
  modal('Save a link to this plan','<p>Bookmark this link to return to <strong>'+esc(record.roadmap.title)+'</strong> and keep editing in this browser.</p><label class="field"><span>Editable plan link</span><textarea id="plan-return-url" rows="3" readonly>'+esc(url)+'</textarea></label><div class="dialog-actions"><button id="copy-return-url" class="button primary" type="button">Copy plan link</button></div><div class="feature-note"><strong>Stored on this device:</strong> This link does not contain your plan data and will not restore it on another device or after clearing browser data. Export a <a href="./docs/saving.html">workspace backup</a> to protect your work.</div>');
  $('#copy-return-url').onclick=async()=>{try{await navigator.clipboard.writeText(url);toast('Editable plan link copied.');}catch{$('#plan-return-url').focus();$('#plan-return-url').select();toast('Select and copy the plan link.');}};
}
function publishDialog(){
  if(!state.record)return;
  modal('Publish a polished roadmap','<p>Create a presentation-ready, read-only roadmap with progress, workstreams and expandable activity details. The published link contains a snapshot of the selected plan.</p><label class="dependency-option"><input type="checkbox" id="publish-owners"><span>Include owner names (off by default)</span></label><label class="dependency-option"><input type="checkbox" id="publish-descriptions" checked><span>Include activity descriptions</span></label><div class="feature-note"><strong>Before publishing:</strong> Anyone with the full link can read the included data, including the plan title, client/workspace label and activity names. There is no password, revocation or automatic update. Publish again after making changes. <a href="./docs/publishing.html">How publishing works</a>.</div><div class="dialog-actions"><button type="button" id="generate-published-link" class="button primary">Generate published link</button></div><div id="generated-published-link" aria-live="polite"></div>');
  $('#generate-published-link').onclick=async()=>{
    const b=$('#generate-published-link');b.disabled=true;
    try{
      const base=new URL('published.html',new URL('./',location.href));
      const url=await makeShareUrl(callbacks.getRoadmap(),base.href,{includeOwners:$('#publish-owners').checked,includeDescriptions:$('#publish-descriptions').checked});
      $('#generated-published-link').innerHTML='<label class="field"><span>Your published roadmap link</span><textarea id="published-url" readonly rows="4">'+esc(url)+'</textarea></label><div class="dialog-actions"><button class="button primary" id="copy-published-url">Copy published link</button><a class="button" href="'+esc(url)+'" target="_blank" rel="noopener noreferrer">'+icon("arrow-up-right")+' Open published view</a></div><p class="field-note">This snapshot is self-contained. The original remains editable in this browser; republish to reflect new changes.</p>';
      $('#copy-published-url').onclick=async()=>{try{await navigator.clipboard.writeText(url);toast('Published roadmap link copied.');}catch{$('#published-url').focus();$('#published-url').select();toast('Select and copy the published link.');}};
    }catch(error){errorInModal(error);}finally{b.disabled=false;}
  };
}
